// WSK-43a — the media upload token: format, hashing, lifetime and the log-redaction rule, in ONE place that
// both halves import (the control plane mints, the public upload route redeems), so they cannot drift.
//
// THE TOKEN IS A BEARER CAPABILITY, exactly as a draft-preview token is (delivery/preview-token.ts): 32
// random bytes from the OS CSPRNG, base64url (43 characters), generated by the api and shown once. Only
// sha256(token) as lowercase hex is stored (migration 0014, media_upload_tokens.token_hash). No pepper: the
// input has 256 bits of entropy. The public route hashes what it was given and asks the unique index for
// that hash, so plaintext is never compared and a lookup's timing reveals nothing about any stored token.
import { createHash, randomBytes } from "node:crypto";

/** How long a minted token stays valid (seconds). "About ten minutes": long enough to pick a file, short enough to be a leaked-link non-event. */
export const UPLOAD_TOKEN_TTL_SECONDS = 600;

/** Exactly what mintUploadToken() produces: 32 bytes as unpadded base64url. */
export const UPLOAD_TOKEN_RE = /^[A-Za-z0-9_-]{43}$/;

export function mintUploadToken(): string {
  return randomBytes(32).toString("base64url");
}

/** sha256(token), lowercase hex: what media_upload_tokens.token_hash holds and what the public route looks up. */
export function hashUploadToken(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}

/** The path of the public upload route for a token. Contains the credential: never log it, never store it. */
export function uploadPathFor(tenantSlug: string, token: string): string {
  return `/v1/t/${tenantSlug}/media/upload/${token}`;
}

/** Is this request path the public upload route? (`/v1/t/<slug>/media/upload/<token>`, query already stripped.) */
export function isUploadPath(path: string): boolean {
  return /^\/v1\/t\/[^/]+\/media\/upload\/[^/]+\/?$/.test(path);
}
